import { NextResponse, type NextRequest } from "next/server";
import { z } from "zod";
import { getServerSupabase } from "@/lib/supabase/server";
import { supabaseEnabled, prodFailClosed, demoLoginEnabled, DEMO_COOKIE_NAME } from "@/lib/supabase/config";
import { demoAuthConfigured, verifyDemoToken } from "@/lib/demo-auth";
import { validateBody } from "@/lib/api/validate";
import { can } from "@/lib/rbac";
import type { Role } from "@/lib/types";
import { checkRateLimit, rateLimitKey, tooManyRequests } from "@/lib/rate-limit";
import { searchGithubUsers, getGithubUser, type GithubUser } from "@/lib/sourcing/github";
import { SOURCE_PLATFORMS } from "@/lib/types";
import { isWebSearchPlatform, extractLead, type WebLead } from "@/lib/sourcing/web-leads";
import { runWebTool } from "@/lib/ai/web-tools";
import { resolveStoredTavilyKey } from "@/lib/sourcing/tavily";

/**
 * Real candidate sourcing.
 *
 * platform "GitHub" (default): searches GitHub for real people via the Users
 * Search API. Runs keyless by default (GitHub's anonymous API quota, 60
 * req/hour/IP) — no signup required. An optional GITHUB_TOKEN, resolved
 * server-side and never returned to the client, raises that ceiling to 5,000
 * req/hour.
 *
 * platform in {LinkedIn, Stack Overflow, Dribbble, Behance}: no free structured
 * search API exists for these, so real candidates are discovered via the
 * existing compliant web_search tool (site:-scoped), same honesty/read-only
 * guarantees as the chat research tools.
 *
 * platform in {Referral, Talent Pool}: not externally sourceable — these are
 * internal-pipeline concepts, not searched at all.
 *
 * Read-only throughout: never writes to GitHub, never logs into or scrapes a
 * platform, never posts a message.
 *
 * `username` (optional): manual single-profile intake. When present, `query`
 * is ignored entirely and the request resolves that one GitHub login via
 * GET /users/{login} instead of running a search.
 */
const GITHUB_USERNAME_RE = /^[a-zA-Z\d](?:[a-zA-Z\d]|-(?=[a-zA-Z\d])){0,38}$/;

const SourceSchema = z
  .object({
    query: z.string().min(1).max(256).optional(),
    username: z.string().min(1).max(39).regex(GITHUB_USERNAME_RE, "Not a valid GitHub username.").optional(),
    count: z.number().int().min(1).max(20).default(8),
    platform: z.enum(SOURCE_PLATFORMS).default("GitHub"),
  })
  .refine((data) => Boolean(data.username?.trim()) || Boolean(data.query?.trim()), {
    message: "query or username is required.",
    path: ["query"],
  });

function publicDemoSourceDenied(req: NextRequest): Response | null {
  if (supabaseEnabled || !demoLoginEnabled) return null;
  if (demoAuthConfigured() && verifyDemoToken(req.cookies.get(DEMO_COOKIE_NAME)?.value)) return null;
  return NextResponse.json({ ok: false, error: "Sign in to use live sourcing." }, { status: 401 });
}

export async function POST(req: NextRequest) {
  const prodBlock = prodFailClosed();
  if (prodBlock) return prodBlock;
  const demoBlock = publicDemoSourceDenied(req);
  if (demoBlock) return demoBlock;

  const rl = checkRateLimit(rateLimitKey(req, "source"), { windowMs: 60_000, max: 10 });
  if (!rl.ok) return tooManyRequests(rl.retryAfterSec);

  let tavilyKey: string | null = null;

  // Live mode: require an authenticated user with the `source` permission. Demo
  // mode (no backend) is open but still rate-limited.
  if (supabaseEnabled) {
    const supabase = await getServerSupabase();
    if (!supabase) return NextResponse.json({ ok: false, error: "No Supabase client." }, { status: 500 });
    const {
      data: { user },
    } = await supabase.auth.getUser();
    if (!user) return NextResponse.json({ ok: false, error: "Not authenticated." }, { status: 401 });
    const { data: role } = await supabase.rpc("current_profile_role");
    if (!can(role as Role, "source")) {
      return NextResponse.json({ ok: false, error: "Insufficient permissions." }, { status: 403 });
    }
    tavilyKey = await resolveStoredTavilyKey(supabase);
  }

  const validated = await validateBody(req, SourceSchema, { maxBytes: 10_000 });
  if (!validated.ok) return validated.response;
  const { query, username, count = 8, platform = "GitHub" as const } = validated.data;

  // Manual single-profile intake: resolve exactly the named GitHub login,
  // ignoring `query` and `count` entirely — this is a lookup, not a search.
  if (username) {
    const token = process.env.GITHUB_TOKEN ?? "";
    try {
      const user = await getGithubUser(username, token);
      if (!user) {
        return NextResponse.json({ ok: false, error: "GitHub user not found." }, { status: 404 });
      }
      return NextResponse.json({ ok: true, source: "github", users: [user] });
    } catch (err) {
      const detail = err instanceof Error ? err.message : "GitHub lookup failed.";
      return NextResponse.json({ ok: false, source: "github", error: detail }, { status: 502 });
    }
  }

  // Schema-enforced: username or query is present; username was handled above.
  if (!query) return NextResponse.json({ ok: false, error: "query is required." }, { status: 400 });

  if (platform === "GitHub") {
    const token = process.env.GITHUB_TOKEN ?? "";
    try {
      const users = await searchGithubUsers(query, count, token);
      return NextResponse.json({ ok: true, source: "github", platform, users });
    } catch (err) {
      // GitHub error bodies never contain the token; keep the client message terse.
      const detail = err instanceof Error ? err.message : "GitHub search failed.";
      return NextResponse.json({ ok: false, source: "github", platform, error: detail }, { status: 502 });
    }
  }

  if (isWebSearchPlatform(platform)) {
    const result = await runWebTool("web_search", { query }, { tavilyKey: tavilyKey ?? undefined });
    if (!result.ok) {
      return NextResponse.json(
        { ok: false, source: "web", platform, error: result.error ?? "Web search failed." },
        { status: 502 },
      );
    }
    const content = result.content as { results?: { title: string; url: string; snippet: string }[] } | undefined;

  const maxYearsExperience = yearsMatch.length ? Math.max(...yearsMatch) + 3 : null;

  // Skills
  const requiredSkills = SKILL_DICTIONARY.filter((s) =>
    new RegExp(`(^|[^a-z])${escapeRegExp(s)}([^a-z]|$)`, "i").test(text),
  ).slice(0, 8);
  const niceToHaveSkills = SKILL_DICTIONARY.filter(
    (s) => !requiredSkills.includes(s) && new RegExp(`nice to have[^.]*${escapeRegExp(s)}`, "i").test(lower),
  ).slice(0, 4);

  // Equity / company stage
  const equity = /equity|options|esop|stock/i.test(text);
  const companyStageTarget: CompanyStage[] = /series\s*b/i.test(text)
    ? ["Series A", "Series B"]
    : /series\s*a/i.test(text)
      ? ["Seed", "Series A"]
      : /enterprise|public/i.test(text)
        ? ["Series C+", "Public"]
        : ["Series A", "Series B"];

  // Industry
  const industryExperience = INDUSTRIES.filter((i) => new RegExp(i.replace("/", ".?"), "i").test(text)).slice(0, 2);

  const validationWarnings: ValidationWarning[] = [];
  if (salaryMin == null)
    validationWarnings.push({ field: "salary", severity: "warning", message: "No salary range provided." });
  if (locationType === "Hybrid" && !/hybrid/i.test(text))
    validationWarnings.push({ field: "location", severity: "info", message: "Location type inferred (defaulted to Hybrid)." });
  if (requiredSkills.length < 3)
    validationWarnings.push({ field: "requiredSkills", severity: "critical", message: "Fewer than 3 required skills detected. JD may be vague." });
  if (minYearsExperience == null)
    validationWarnings.push({ field: "experience", severity: "warning", message: "No years-of-experience band specified." });

  const jobAnalysis: JobAnalysis = {
    title,
    department,
    seniority,
    employmentType: /\b(contractor|freelance|contract role|contract position|fixed[- ]term|day rate)\b/i.test(text)
      ? "Contract"
      : "Full-time",
    locationType,
    regions: Array.from(new Set(regions)),
    timezone: tzMatch,
    salaryMin,
    salaryMax,
    currency,
    equity,
    requiredSkills: requiredSkills.length ? requiredSkills : ["TypeScript", "Node.js", "PostgreSQL"],
    niceToHaveSkills,
    minYearsExperience,
    maxYearsExperience,
    education: /phd|master|bachelor|degree/i.test(text)
      ? (text.match(/phd|master'?s|bachelor'?s/i)?.[0] ?? "Degree preferred")
      : "No formal requirement",
    industryExperience,
    companyStageTarget,
    teamSize: text.match(/team of (\d+)/i)?.[0] ?? "6–10 engineers",
    reportingTo: text.match(/report(?:s|ing) to (?:the )?([A-Za-z ]+?)[.,\n]/i)?.[1]?.trim() ?? "Engineering Manager",
    urgency,
    language: detectLanguage(text),
    validationWarnings,
  };

  const hasCritical = validationWarnings.some((w) => w.severity === "critical") || salaryMin == null;
  const clarificationDraft = hasCritical ? buildClarificationEmail(nameMatch, jobAnalysis, validationWarnings) : null;

  return {
    sender: { name: nameMatch, email: senderEmail },
    intent,
    urgency,
    jobAnalysis,
    validationWarnings,
    clarificationDraft,
    confidence: {
      title: requiredSkills.length > 4 ? 0.92 : 0.74,
      salary: salaryMin != null ? 0.9 : 0.4,
      skills: clamp(0.55 + requiredSkills.length * 0.05, 0.5, 0.95),
      location: locationType === "Remote" ? 0.9 : 0.7,
      seniority: 0.85,
    },
  };
}

/** Exported so the live intake parser (src/lib/ai/intake.ts) can build the same
 *  clarification draft off a live-parsed JobAnalysis — kept in one place so the
 *  copy stays identical between the heuristic and live paths. */
export function buildClarificationEmail(name: string, jd: JobAnalysis, warnings: ValidationWarning[]): string {
  const asks = warnings.map((w) => `• ${w.message}`).join("\n");
  return `Hi ${name.split(" ")[0]},

Thanks for the brief on the ${jd.title} role. I'll kick off sourcing right away. To target the right people and avoid wasted outreach, could you confirm a few details:

${asks}
• Confirmed budget band and whether equity is on the table
• Must-have vs. nice-to-have skills, if any flexibility

I'll spin up the campaign the moment these land. In the meantime I've drafted a provisional profile so we lose no time.

Best,
Aria Sourcing`;
}

